//! Tab and workspace names.
//!
//! Names are part of shprd's interface: a human reads them on the tab bar to
//! know which agent is which, so they are generated by one function no matter
//! which multiplexer hosts them, and they are stable enough that a re-created
//! tab comes back with the name it had.

/// What an agent, or the human's own shell, is doing in a tab.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Role {
    /// A tab opened for the human to chat with shprd; it hosts no agent.
    Chat,
    /// The orchestrator agent that plans and delegates.
    Orchestrator,
    /// An agent working one task in its own worktree.
    Worker,
    /// An agent reviewing someone else's diff.
    Reviewer,
}

/// The longest label kept verbatim; longer labels are cut at a char boundary.
pub const LABEL_MAX_CHARS: usize = 16;

/// The glyph that prefixes a tab title, or `""` for the chat tab.
///
/// A dry run marks every agent with `◌` instead of its role glyph, so a
/// screenshot of the tab bar says "nothing is really running".
pub fn symbol(role: Role, dry: bool) -> &'static str {
    match role {
        Role::Chat => "",
        _ if dry => "◌",
        Role::Orchestrator => "★",
        Role::Worker => "●",
        Role::Reviewer => "◇",
    }
}

/// Shorten `label` to [`LABEL_MAX_CHARS`] characters (never bytes, so a
/// multibyte label cannot be cut mid-character) and drop any separator it was
/// left ending with, so `feat/m4-mux-that-never-end` does not read as a word
/// boundary that is not there.
pub fn truncate_label(label: &str) -> String {
    let mut cut: String = label.chars().take(LABEL_MAX_CHARS).collect();
    if cut.chars().count() < label.chars().count() {
        cut = cut.trim_end_matches(['-', ' ']).to_string();
    }
    cut
}

/// The title for a tab: `shprd·chat` for the human's tab, otherwise
/// `<symbol> <cli>·<label>`.
pub fn tab_title(role: Role, cli: &str, label: &str, dry: bool) -> String {
    if role == Role::Chat {
        return String::from("shprd·chat");
    }
    format!("{} {}·{}", symbol(role, dry), cli, truncate_label(label))
}

/// Make `wanted` unique against the titles already in use.
///
/// Only a collision costs anything, and the tag it appends grows until it is
/// unique: the first four characters of `suffix` (the task id, say), then more
/// of it, and finally the whole suffix with a counter. Two workers on similar
/// branches therefore stay distinguishable even when their first four
/// characters agree.
pub fn disambiguate(titles: &[String], wanted: &str, suffix: &str) -> String {
    let taken = |candidate: &str| titles.iter().any(|title| title == candidate);
    if !taken(wanted) {
        return wanted.to_string();
    }
    let chars: Vec<char> = suffix.chars().collect();
    for len in 4.min(chars.len())..=chars.len() {
        let tag: String = chars[..len].iter().collect();
        let candidate = format!("{wanted}·{tag}");
        if !taken(&candidate) {
            return candidate;
        }
    }
    // Even the full suffix collided: number the tags until one is free.
    let mut n: u32 = 2;
    loop {
        let candidate = format!("{wanted}·{suffix}{n}");
        if !taken(&candidate) {
            return candidate;
        }
        n += 1;
    }
}

/// The workspace name for a repository: `shprd · <repo_name>`.
///
/// One workspace per repository is the whole point, so the name is derived from
/// the repo alone and survives a restart.
pub fn workspace_name(repo_name: &str) -> String {
    format!("shprd · {repo_name}")
}

#[cfg(test)]
mod tests {
    use super::{
        LABEL_MAX_CHARS, Role, disambiguate, symbol, tab_title, truncate_label, workspace_name,
    };

    #[test]
    fn symbols_mark_role_and_dry_run() {
        assert_eq!(symbol(Role::Orchestrator, false), "★");
        assert_eq!(symbol(Role::Worker, false), "●");
        assert_eq!(symbol(Role::Reviewer, false), "◇");
        assert_eq!(symbol(Role::Chat, false), "");
        assert_eq!(symbol(Role::Orchestrator, true), "◌");
        assert_eq!(symbol(Role::Worker, true), "◌");
        assert_eq!(symbol(Role::Reviewer, true), "◌");
        assert_eq!(symbol(Role::Chat, true), "");
    }

    #[test]
    fn titles_per_role() {
        assert_eq!(
            tab_title(Role::Chat, "claude", "anything", false),
            "shprd·chat"
        );
        assert_eq!(
            tab_title(Role::Chat, "claude", "anything", true),
            "shprd·chat"
        );
        assert_eq!(
            tab_title(Role::Orchestrator, "claude", "orch", false),
            "★ claude·orch"
        );
        assert_eq!(
            tab_title(Role::Worker, "codex", "m4-mux", false),
            "● codex·m4-mux"
        );
        assert_eq!(
            tab_title(Role::Worker, "codex", "m4-mux", true),
            "◌ codex·m4-mux"
        );
        assert_eq!(tab_title(Role::Reviewer, "pi", "pr-7", false), "◇ pi·pr-7");
    }

    #[test]
    fn long_multibyte_label_is_cut_by_chars() {
        let label = "とても長い日本語のラベルですねそうです";
        let cut = truncate_label(label);
        assert_eq!(cut.chars().count(), LABEL_MAX_CHARS);
        let title = tab_title(Role::Worker, "claude", label, false);
        assert_eq!(title, format!("● claude·{cut}"));
        assert!(title.chars().all(|c| c != '\u{fffd}'));
    }

    #[test]
    fn truncation_drops_a_trailing_separator() {
        assert_eq!(truncate_label("feat/m4-mux-abcdefgh"), "feat/m4-mux-abcd");
        assert_eq!(
            truncate_label("abcdefghijklmno-and-more"),
            "abcdefghijklmno"
        );
        assert_eq!(truncate_label("shprd worker-xyz "), "shprd worker-xyz");
        assert_eq!(truncate_label("short"), "short");
    }

    #[test]
    fn disambiguation_only_on_collision() {
        let titles = vec!["● claude·m4-mux".to_string(), "★ claude·orch".to_string()];
        assert_eq!(
            disambiguate(&titles, "● claude·m4-mux-dev", "M4.1"),
            "● claude·m4-mux-dev"
        );
        assert_eq!(
            disambiguate(&titles, "● claude·m4-mux", "M4.1"),
            "● claude·m4-mux·M4.1"
        );
        assert_eq!(disambiguate(&[], "shprd·chat", "M4.1"), "shprd·chat");
    }

    #[test]
    fn disambiguation_grows_the_tag_until_unique() {
        let wanted = "● claude·m4-mux";
        let titles = vec![wanted.to_string(), format!("{wanted}·abcd")];
        assert_eq!(
            disambiguate(&titles, wanted, "abcdefgh"),
            format!("{wanted}·abcde")
        );
        // Every prefix of the suffix taken: fall back to numbering it.
        let mut titles = titles;
        for len in 5..=8 {
            titles.push(format!("{wanted}·{}", &"abcdefgh"[..len]));
        }
        assert_eq!(
            disambiguate(&titles, wanted, "abcdefgh"),
            format!("{wanted}·abcdefgh2")
        );
        titles.push(format!("{wanted}·abcdefgh2"));
        assert_eq!(
            disambiguate(&titles, wanted, "abcdefgh"),
            format!("{wanted}·abcdefgh3")
        );
    }

    #[test]
    fn workspace_name_names_the_repo() {
        assert_eq!(workspace_name("shprd"), "shprd · shprd");
        assert_eq!(workspace_name("my-repo"), "shprd · my-repo");
    }
}
